program='''def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 6:
                continue
            candidates = [(c, r)]
            if 2 <= r < n and 0 <= 31-r < n:
                candidates.append((31-r, c))
            if 2 <= c < n and 0 <= 31-c < n:
                candidates.append((r, 31-c))
            if 2 <= c < n and 0 <= 31-c < n:
                candidates.append((31-c, r))
            if 2 <= r < n and 0 <= 31-r < n:
                candidates.append((c, 31-r))
            if 2 <= r < n and 2 <= c < n and 0 <= 31-r < n and 0 <= 31-c < n:
                candidates.append((31-r, 31-c))
            for rr, cc in candidates:
                if grid[rr][cc] != 6:
                    out[r][c] = grid[rr][cc]
                    break
    return out
'''
path.write_text(program)
